import{_ as a,o as l,c as o,ai as e}from"./chunks/framework.Ba-VnP44.js";const p=JSON.parse('{"title":"AI 生图实践","description":"","frontmatter":{},"headers":[],"relativePath":"ai/creation/ai-image.md","filePath":"ai/creation/ai-image.md"}'),t={name:"ai/creation/ai-image.md"};function r(n,i,s,d,h,u){return l(),o("div",null,[...i[0]||(i[0]=[e('<h1 id="ai-生图实践" tabindex="-1">AI 生图实践 <a class="header-anchor" href="#ai-生图实践" aria-label="Permalink to “AI 生图实践”">​</a></h1><h2 id="场景与问题" tabindex="-1">场景与问题 <a class="header-anchor" href="#场景与问题" aria-label="Permalink to “场景与问题”">​</a></h2><p>写博客、做封面、配信息图，图是躲不开的环节。传统的路子要么自己画（不会），要么找设计师（没预算），要么搜图（版权悬着）。AI 生图出来后看似解决了，真用起来又是新问题：</p><ul><li>同一张图重 roll 十几次，能看的没几张，能用的更少；</li><li>博客封面今天一个风格明天一个风格，首页看着像拼贴站；</li><li>提示词写一大段，出来的东西和想的完全两回事，改都不知道从哪改；</li><li>随手用生成图做商用封面、产品页配图，版权条款没看过，哪天收到投诉都不知道为什么。</li></ul><p>生图工具的门槛已经很低了，真正的门槛是三件事：<strong>把想法翻译成提示词、让整组图保持一致、知道什么图能商用</strong>。</p><h2 id="做法" tabindex="-1">做法 <a class="header-anchor" href="#做法" aria-label="Permalink to “做法”">​</a></h2><h3 id="_1-提示词结构-四个槽位-而不是一串形容词" tabindex="-1">1. 提示词结构：四个槽位，而不是一串形容词 <a class="header-anchor" href="#_1-提示词结构-四个槽位-而不是一串形容词" aria-label="Permalink to “1. 提示词结构：四个槽位，而不是一串形容词”">​</a></h3><p>有效的提示词不是堆砌&quot;高清、8K、大师作品&quot;，而是按槽位组织：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[主体] + [场景/构图] + [风格] + [技术参数]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><strong>主体</strong>：谁/什么，越具体越好。&quot;一个对着三块屏幕排查日志的后端工程师&quot; 优于 &quot;一个程序员&quot;；</li><li><strong>场景与构图</strong>：视角、布局、留白。&quot;俯视桌面、笔记本居中、右侧留出 1/3 空白放标题文字&quot;；</li><li><strong>风格</strong>：扁平插画 / 写实摄影 / 3D 渲染 / 线稿，一种就够，混搭会互相打架；</li><li><strong>技术参数</strong>：比例（16:9 封面）、光线、色调，按平台要求给。</li></ul><p>两个实用习惯：</p><ul><li><strong>先跑结构，再调形容</strong>：主体和构图定了八成效果，风格词是微调，不要指望形容词救构图；</li><li><strong>负面提示词同步写</strong>：不想看到的（文字水印、畸形手、模糊、logo）列进 negative prompt，能挡掉一大半废片。</li></ul><h3 id="_2-风格一致性-把-风格-沉淀成可复用的配方" tabindex="-1">2. 风格一致性：把&quot;风格&quot;沉淀成可复用的配方 <a class="header-anchor" href="#_2-风格一致性-把-风格-沉淀成可复用的配方" aria-label="Permalink to “2. 风格一致性：把&quot;风格&quot;沉淀成可复用的配方”">​</a></h3><p>一个栏目/一个站点的图必须看着像一家人。做法是把风格固化成一段可复用的&quot;风格后缀&quot;：</p><ul><li>挑一个基准：选定一张满意的图，反查它当时完整的提示词，从中提炼出风格描述（配色、笔触、光线）；</li><li>固定成模板：<code>…… , flat illustration, indigo &amp; orange palette, soft shadows, minimal, no text</code>，每次生成只换主体，风格段原样保留；</li><li>更省事的做法是用图生图/垫图：拿上一张成图当参考图，权重调低（0.3-0.5），保持风格的同时换内容；</li><li>工具侧：Midjourney 用 <code>--sref</code> / moodboard，ComfyUI 存 workflow 和 LoRA，把配方落到工具里。</li></ul><p><strong>一次定风格，后面全部复用</strong>。不要每次从零写提示词，那必然跑偏。</p><h3 id="_3-封面图与配图的生产流程" tabindex="-1">3. 封面图与配图的生产流程 <a class="header-anchor" href="#_3-封面图与配图的生产流程" aria-label="Permalink to “3. 封面图与配图的生产流程”">​</a></h3><p>我自己的两类图，流程分开：</p><p><strong>封面图（每篇一张，要求稳定出片）</strong></p><ol><li>从文章标题提炼一个核心意象（&quot;流水线&quot;就画传送带，&quot;事实核查&quot;就画放大镜）；</li><li>用固定的风格后缀 + 意象主体生成，比例锁定 16:9；</li><li>一次生成 4-8 张，只挑构图对的（细节可后期），不纠结完美；</li><li>统一后处理：套同一个调色/加噪预设，封面尺寸批量裁剪，保证列表页整齐。</li></ol><p><strong>正文配图（服务于理解，不追求好看）</strong></p><ul><li>优先级一永远是<strong>图表自己画</strong>：流程图、架构图用 Mermaid / draw.io，AI 生图不擅长精确表达逻辑；</li><li>AI 只负责&quot;氛围图&quot;和概念示意：章节头图、抽象概念配图；</li><li>配图命名跟随文章：<code>2026-10-ai-writing-cover.png</code>，别用 <code>image(3).png</code>。</li></ul><h3 id="_4-版权与商用-用之前先看清条款" tabindex="-1">4. 版权与商用：用之前先看清条款 <a class="header-anchor" href="#_4-版权与商用-用之前先看清条款" aria-label="Permalink to “4. 版权与商用：用之前先看清条款”">​</a></h3><p>三档区分，按用途对号入座：</p><ul><li><strong>免费档（CC0 类）</strong>：部分模型/平台明确商用免费、无需署名，但要注意训练数据争议在部分地区仍有诉讼；</li><li><strong>订阅档（Midjourney、DALL·E 等付费）</strong>：付费用户通常可商用，但<strong>版权归属和免责条款各平台不同</strong>，发布前看 ToS 的 &quot;ownership / commercial use&quot; 段落；</li><li><strong>红线</strong>：不生成真人人脸（肖像权）、不模仿在世艺术家的签名风格用于商用、不生成带他人商标/logo 的图、谨慎生成&quot;某某公司产品图&quot;。</li></ul><p>另外两个工程习惯：<strong>保留生成记录</strong>（提示词、模型、时间、账号），万一需要证明来源时是唯一的凭据；商用图优先选付费档，省下的钱不够一次纠纷的成本。</p><h2 id="关键要点" tabindex="-1">关键要点 <a class="header-anchor" href="#关键要点" aria-label="Permalink to “关键要点”">​</a></h2><ul><li>提示词按&quot;主体 + 场景构图 + 风格 + 技术参数&quot;四槽位写，负面提示词同步给；</li><li>风格一致性靠&quot;固定风格后缀 / 垫图 / sref 配方&quot;，一次沉淀，全程复用；</li><li>逻辑图自己画（Mermaid 等），AI 只做封面和氛围图；封面构图优先，细节靠后处理；</li><li>生成记录要留存；商用前查平台 ToS，避开人脸、在世艺术家风格、他人商标三条红线；</li><li>出片靠批量筛选不靠单张神抽：一次出 4-8 张，挑构图，别恋战。</li></ul><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p>AI 生图对内容创作者的价值，不是&quot;会画&quot;，而是<strong>把配图从外部依赖变成内部流水线</strong>。提示词模板化、风格配方化、流程步骤化之后，一张封面从两小时外包变成五分钟筛选，且整站图风格统一。把版权那几条规矩守好，这条流水线就能放心跑很久。</p>',30)])])}const c=a(t,[["render",r]]);export{p as __pageData,c as default};
